import csv,sqlite3, json
with open('json/molecule.json') as f:
    mol = {r['molecule_id']: r['label'] for r in json.load(f)['records']}
con = sqlite3.connect('db/bond.db')
bonds = {}
for r in con.execute('SELECT molecule_id, bond_type FROM bond'):
    mid, bt = r
    if mid not in bonds: bonds[mid] = set()
    bonds[mid].add(bt)
con.close()
triple_mols = {mid for mid, bts in bonds.items() if '#' in bts}
print('Triple molecules:', triple_mols)
result = []
with open('csv/atom.csv') as f:
    for r in csv.DictReader(f):
        if r['molecule_id'] in triple_mols and r['element'] in ['p', 'br']:
            result.append((r['atom_id'], r['element'], r['molecule_id']))
print('Result:', result)
print('Count:', len(result))

